#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeLayersCoreHandle: FfiConverter {
    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = LayersCoreHandle

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> LayersCoreHandle {
        return LayersCoreHandle(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: LayersCoreHandle) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LayersCoreHandle {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if ptr == nil {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: LayersCoreHandle, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeLayersCoreHandle_lift(_ pointer: UnsafeMutableRawPointer) throws -> LayersCoreHandle {
    return try FfiConverterTypeLayersCoreHandle.lift(pointer)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeLayersCoreHandle_lower(_ value: LayersCoreHandle) -> UnsafeMutableRawPointer {
    return FfiConverterTypeLayersCoreHandle.lower(value)
}

/**
 * Configuration record for initializing the SDK from Swift/Kotlin.
 *
 * Only contains primitive types that UniFFI can marshal. The Rust side
 * constructs internal trait-object fields (HTTP client, persistence backend)
 * automatically.
 */
public struct UniFfiConfig {
    public let appId: String
    public let environment: LayersEnvironment
    public let baseUrl: String?
    public let flushIntervalMs: UInt64?
    public let flushThreshold: UInt32?
    public let maxQueueSize: UInt32?
    public let maxBatchSize: UInt32?
    public let enableDebug: Bool?
    /**
     * Enable per-device DebugView. When true, the SDK mints + persists a
     * stable UUID and sends it in the `X-Debug-Token` header on every
     * request. Retrieve via [`LayersCoreHandle::debug_token`].
     */
    public let debug: Bool?
    public let sdkVersion: String?
    /**
     * Directory for file-based event persistence.
     */
    public let persistenceDir: String?
    /**
     * Web wrappers respect the browser DNT signal when true. Native
     * platforms have no equivalent and ignore this flag.
     */
    public let respectDnt: Bool?
    /**
     * Web cookieless identification mode. Adds `X-Cookieless: true` to
     * every flush. Native platforms ignore this flag.
     */
    public let cookielessMode: Bool?
    /**
     * Opt-in-by-default mode. Queue events but do not flush until the
     * host app makes its first explicit `set_consent` call.
     */
    public let consentRequired: Bool?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(appId: String, environment: LayersEnvironment, baseUrl: String?, flushIntervalMs: UInt64?, flushThreshold: UInt32?, maxQueueSize: UInt32?, maxBatchSize: UInt32?, enableDebug: Bool?,
                /**
                    * Enable per-device DebugView. When true, the SDK mints + persists a
                    * stable UUID and sends it in the `X-Debug-Token` header on every
                    * request. Retrieve via [`LayersCoreHandle::debug_token`].
                    */ debug: Bool?, sdkVersion: String?,
                /**
                    * Directory for file-based event persistence.
                    */ persistenceDir: String?,
                /**
                    * Web wrappers respect the browser DNT signal when true. Native
                    * platforms have no equivalent and ignore this flag.
                    */ respectDnt: Bool?,
                /**
                    * Web cookieless identification mode. Adds `X-Cookieless: true` to
                    * every flush. Native platforms ignore this flag.
                    */ cookielessMode: Bool?,
                /**
                    * Opt-in-by-default mode. Queue events but do not flush until the
                    * host app makes its first explicit `set_consent` call.
                    */ consentRequired: Bool?)
    {
        self.appId = appId
        self.environment = environment
        self.baseUrl = baseUrl
        self.flushIntervalMs = flushIntervalMs
        self.flushThreshold = flushThreshold
        self.maxQueueSize = maxQueueSize
        self.maxBatchSize = maxBatchSize
        self.enableDebug = enableDebug
        self.debug = debug
        self.sdkVersion = sdkVersion
        self.persistenceDir = persistenceDir
        self.respectDnt = respectDnt
        self.cookielessMode = cookielessMode
        self.consentRequired = consentRequired
    }
}

extension UniFfiConfig: Equatable, Hashable {
    public static func == (lhs: UniFfiConfig, rhs: UniFfiConfig) -> Bool {
        if lhs.appId != rhs.appId {
            return false
        }
        if lhs.environment != rhs.environment {
            return false
        }
        if lhs.baseUrl != rhs.baseUrl {
            return false
        }
        if lhs.flushIntervalMs != rhs.flushIntervalMs {
            return false
        }
        if lhs.flushThreshold != rhs.flushThreshold {
            return false
        }
        if lhs.maxQueueSize != rhs.maxQueueSize {
            return false
        }
        if lhs.maxBatchSize != rhs.maxBatchSize {
            return false
        }
        if lhs.enableDebug != rhs.enableDebug {
            return false
        }
        if lhs.debug != rhs.debug {
            return false
        }
        if lhs.sdkVersion != rhs.sdkVersion {
            return false
        }
        if lhs.persistenceDir != rhs.persistenceDir {
            return false
        }
        if lhs.respectDnt != rhs.respectDnt {
            return false
        }
        if lhs.cookielessMode != rhs.cookielessMode {
            return false
        }
        if lhs.consentRequired != rhs.consentRequired {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(appId)
        hasher.combine(environment)
        hasher.combine(baseUrl)
        hasher.combine(flushIntervalMs)
        hasher.combine(flushThreshold)
        hasher.combine(maxQueueSize)
        hasher.combine(maxBatchSize)
        hasher.combine(enableDebug)
        hasher.combine(debug)
        hasher.combine(sdkVersion)
        hasher.combine(persistenceDir)
        hasher.combine(respectDnt)
        hasher.combine(cookielessMode)
        hasher.combine(consentRequired)
    }
}

