        case 3: return .drop

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: UniFfiFlushDisposition, into buf: inout [UInt8]) {
        switch value {
        case .delivered:
            writeInt(&buf, Int32(1))

        case .retryLater:
            writeInt(&buf, Int32(2))

        case .drop:
            writeInt(&buf, Int32(3))
        }
    }
}

