    @_documentation(visibility: private)
#endif
extension FfiConverterCallbackInterfaceUniFfiBeforeSendCallback: FfiConverter {
    typealias SwiftType = UniFfiBeforeSendCallback
    typealias FfiType = UInt64

    #if swift(>=5.8)
        @_documentation(visibility: private)
    #endif
